<script setup>
import { computed } from 'vue'
const props=defineProps({values:{type:Array,default:()=>[]},labels:{type:Array,default:()=>[]},title:String})
const normalized=computed(()=>{const rows=props.values.length?props.values:[.28,.42,.61,.48,.72,.53,.36,.57,.31];const min=Math.min(...rows),max=Math.max(...rows);return rows.map((value,index)=>({value:Number(value),label:props.labels[index]||`Zone ${index+1}`,strength:max===min?.5:(Number(value)-min)/(max-min)}))})
</script>
<template><div class="zone"><header><b>{{title||'ZONE PROFILE'}}</b><span>HOVER FOR DETAIL</span></header><div class="zone-grid"><span v-for="cell in normalized" :key="cell.label" :style="{'--heat-pct':`${7+cell.strength*66}%`,'--border-pct':`${12+cell.strength*48}%`}" :title="`${cell.label}: ${cell.value.toFixed(3)}`"><b>{{cell.value.toFixed(cell.value<1?3:1)}}</b><small>{{cell.label}}</small></span></div><footer>Values are derived from available matchup metrics; unavailable zone-level evidence is never synthesized.</footer></div></template>
<style scoped>.zone{display:grid;gap:13px}.zone header{display:flex;justify-content:space-between;font:700 7px 'DM Mono';color:var(--muted)}.zone-grid{aspect-ratio:1;display:grid;grid-template-columns:repeat(3,1fr);gap:4px;padding:8px;border:1px solid var(--line);background:var(--raised)}.zone-grid span{display:grid;place-items:center;align-content:center;gap:4px;background:color-mix(in srgb,var(--sport,var(--accent)) var(--heat-pct),var(--surface));border:1px solid color-mix(in srgb,var(--sport,var(--accent)) var(--border-pct),var(--line))}.zone-grid b{font:800 13px 'DM Mono'}.zone-grid small{font:600 6px 'DM Mono';color:var(--muted)}.zone footer{font-size:7px;line-height:1.5;color:var(--muted)}</style>
